import sys, json; sys.path.insert(0, '/home/user/artificial-reef-survey/08_paper/data/src')
from common import *
SL = 'boscombe-surf-reef'
SH = '07_scale/shapes/boscombe-surf-reef/'
AL = dict(GLOBAL_ALIASES, Mead2010=r'Mead, S\., Blenkinsopp', Rendle2016=r'Rendle, E\.J\. \(2016\)', RendleDavidson2012=r'Rendle, E\.J\. and Davidson', WikiBoscombe=r'Wikipedia \(2026, accessed\)\. "Boscombe', Breaker2018=r'The Breaker \(2018\)', RWR=r'Raised Water Research \(n\.d\.\)\. "Boscombe',
          Breaker=r'The Breaker \(n\.d\.\)', Newsroom=r'Reid|Newsroom\.co\.nz', Geosynth=r'Geosynthetics Magazine')
PB = json.load(open(f'{ROOT}/08_paper/data/profile_boscombe.json')); T = PB['transect']
def build():
    r = Reef(SL, AL)
    r.F('name', 'Boscombe Surf Reef, Boscombe, Bournemouth, Dorset (Poole Bay)', 'text', 'S', 'Blacka2013', 'Table 4.2 p.66')
    r.F('country', 'United Kingdom (England)', 'text', 'S', 'Mead2010', 'title')
    r.F('lat', 50.717532, 'deg N (WGS84)', 'D', 'repo:' + SH + 'shape.json geo.centroid_latlon', 'centroid of the outline traced on Esri Wayback 28 Sep 2011; same as the page')
    r.F('lon', -1.838909, 'deg E (WGS84)', 'D', 'repo:' + SH + 'shape.json geo.centroid_latlon', 'as lat')
    r.F('year_built', 2008, 'year (construction start)', 'S', 'Rendle2016', 'p.64: construction started 30 Aug 2008, suspended 13 Nov 2008, resumed 18 Apr 2009', note='Card headline: began June 2008.')
    r.F('year_completed', 2009, 'year', 'S', 'Rendle2016', 'p.64-65: official opening 2 Oct 2009 (p.65: completion Nov 2009 after 18 months); M&B p.4: late September 2009', note='Closed 31 Mar 2011 after container failure; ASR liquidated 2012; re-branded for diving 2014/2017.')
    r.F('purpose', 'multi', 'category', 'S', 'Mead2010', 'title: Design and construction of the Boscombe multi-purpose reef', note='Coastal-town regeneration + surf tourism (double good surf days from ~77 to ~154/yr, Wikipedia/Breaker); Blacka rates protection secondary ("Minor").')
    r.F('material', 'sand-filled non-woven geotextile containers placed by divers/RAD in two layers; 32-55 containers (sources differ), each up to 60-70 m long, 2-5 m diameter', 'text', 'S', 'Rendle2016', 'p.68-69, Table 5.3 p.98 (eight T4 containers ~4 m diameter, 65-70 m long, 746.7 m3 each)')
    r.F('volume_m3', 12800, 'm3 (sand fill, designers)', 'S', 'MeadBorrero2011', 'p.4 (3.1.6)', note='About 13,000 (Mead et al. 2010 via 3D); Rendle design 11,900/12,200; April 2011 survey relief 9,573 m3 (damaged); 3D loft 13,119 m3.',
        alts=[(13000, 'Mead et al. 2010 / RWR', 'S', 'Mead2010', 'cited in METHODS_3D KN'), (11900, 'Rendle design volume', 'S', 'Rendle2016', 'Table 4.4 p.70'), (13119, '3D loft', 'D', 'repo:' + SH + '3d/METHODS_3D.md E10', 'METHODS_3D s3.5')])
    r.F('footprint_area_m2', 4042.2, 'm2 (traced outline)', 'D', 'repo:' + SH + 'shape.json canonical.area_m2', 'outer edge of the bag field on Esri Wayback 28 Sep 2011 (25 vertices); crest plateau 1,780 m2',
        alts=[(10000, '"about 1 ha" (literature)', 'S', 'RWR', 'card size field'), (5450, 'Rendle design footprint', 'S', 'Rendle2016', 'Table 4.4 p.70'), (7200, 'published 80 x 90 m', 'D', 'Blacka2013', 'Table 4.2 p.66 (rectangle area, DERIVED)')])
    r.F('plan_length_alongshore_m', 88.5, 'm', 'D', 'repo:' + SH + 'shape.json canonical.bbox_m.alongshore', '', alts=[(80, 'published', 'S', 'Blacka2013', 'Table 4.2 p.66')])
    r.F('plan_length_crossshore_m', 94.3, 'm', 'D', 'repo:' + SH + 'shape.json canonical.bbox_m.crossshore', '', alts=[(90, 'published', 'S', 'Blacka2013', 'Table 4.2 p.66')])
    r.F('crest_depth_msl_m', 0.90, 'm below MSL', 'D', 'Mead2010+Rendle2016', 'designers: crest height +0.5 m above chart datum (Mead et al. 2010); built crest +0.5 m ACD (Rendle 2016 p.70); ACD = MSL + 1.40 (METHODS_3D E6, Bournemouth CD 1.40 m below ODN, ODN ~ MSL assumed A4) -> 0.90 m below MSL',
        note='Oct 2009 survey tops +0.05 to +0.65 m ACD; April 2011 max +0.68 m ACD (damaged); Blacka submergence 0.5 m. Datum of the survey plot (chart datum) is an assumption: all absolute heights would shift by 1.4 m if it were ODN.')
    r.F('crest_depth_lat_m', -0.56, 'm below LAT (negative = above LAT: dry at LAT)', 'D', 'Mead2010', 'LAT = -0.06 m ACD (METHODS_3D datum), crest +0.5 m ACD -> 0.56 m above LAT')
    r.F('seabed_depth_toe_m', round(T['toe_depth_msl'], 2), 'm below MSL', 'D', 'repo:' + SH + '3d/model.js seabed (April 2011 DGPS survey of Rendle & Davidson 2012 Fig 9, colour read +-0.2 m) + loft rule E10; 08_paper/data/src/derive_boscombe.py', 'bed at the seaward end of the loft on the crest transect (x = %.1f m, y = %.1f m)' % (T['x'], T['y_toe']),
        note='Published: "225 m offshore in 2.7 to 5 m depth" (Rendle & Davidson); design "set in water depths of 3-5 m (CD)" (Mead 2010). Median over columns %.2f m.' % PB['medians']['toe_depth_msl'][0])
    r.F('seabed_depth_at_crest_m', round(T['bed_at_crest_msl'], 2), 'm below MSL', 'D', 'repo:' + SH + '3d/model.js seabed; derive_boscombe.py', 'bed under the seaward crest edge, y = %.1f m' % T['y_crest'], note='Bed under the outline: mean 3.56 m ACD (METHODS_3D KN), %.2f-%.2f m below MSL.' % tuple(PB['bed_under_outline_msl_range']))
    r.F('reef_height_m', 3.2, 'm (mean inside the outline; surveyed median 2.3 m, max 4.1 m after damage)', 'D', 'Rendle2016', 'METHODS_3D KN "Reef height above the seabed"; Rendle Table 4.4 design height 2.8-4.1 m')
    r.F('distance_offshore_crest_m', round(T['y_crest'], 0), 'm from the surf line (shoreline in the model frame)', 'D', 'repo:' + SH + '3d/model.js; derive_boscombe.py', 'seaward crest edge of the loft; outline nearest edge 181 m, centroid 226 m, far edge 276 m offshore of the surf line (METHODS_3D s3.3)',
        alts=[(225, 'published: reef 225 m offshore', 'S', 'RendleDavidson2012', 'cited in METHODS_3D KN "Seabed depth"'), (220, '220 m from the seawall base (card)', 'S', 'RWR', 'card size field')])
    r.F('tide_spring_range_m', 1.76, 'm (MHWS - MLWS)', 'S', 'Mead2010', 'Table 1 water levels at Boscombe (Bournemouth Pier gauge): MHWS 2.21, MLWS 0.45 m ACD; maximum spring range 1.96 m (METHODS_3D s3.2)', note='Poole Bay has a double high water. Blacka Table 4.3: tide range 1.8 m.')
    r.F('tide_mean_range_m', 1.13, 'm', 'D', 'Mead2010', 'MHW = (MHWS+MHWN)/2, MLW = (MLWS+MLWN)/2 from Mead et al. 2010 Table 1 levels (MHWN +0.27, MLWN -0.23 m MSL); neap range 0.50 m')
    r.F('swell_hs_m', 0.5, 'm (typical; basis not stated)', 'S', 'Blacka2013', 'Table 4.3 p.68: T ~4 s, H ~0.5 m', note='Poole Bay is sheltered and low-energy (design swell from 191 deg, Mead et al. 2010 design direction).')
    r.F('swell_tp_s', 4, 's (typical)', 'S', 'Blacka2013', 'Table 4.3 p.68')
    r.F('swell_dir', 'design swell direction 191 deg (S-SSW), Poole Bay', 'text', 'S', 'Mead2010', 'design direction quoted in METHODS_3D / shape.json angles')
    r.F('design_wave', 'designed for the 191 deg swell of Poole Bay; reef built at 3-5 m water depth (CD), 225 m offshore; "built to design", waves "break as expected for the design waves" (designers)', 'text', 'S', 'MeadBorrero2011+Mead2010', 'M&B p.4; Mead et al. 2010')
    r.F('arm_angle_to_shoreline_deg', 55.3, 'deg (envelope long axis; edges 53.8-56.0)', 'D', 'repo:' + SH + 'shape.json angles', 'minimum rotated rectangle of the outline, 121 m long side; shoreline bearing 83.4 deg', note='Seaward block almost shore-normal (6.6 deg); seaward edge 2.6 deg from the shoreline.')
    r.F('arm_angle_to_swell_deg', 72.9, 'deg (geometry only, no refraction)', 'D', 'repo:' + SH + 'shape.json angles', 'reef long axis (28.1 deg) vs the wave-crest line of the 191 deg design swell (crest bearing 101 deg); ignores refraction')
    r.F('surf_outcome', 'works rarely', 'category', 'S', 'WikiBoscombe+Blacka2013+MeadBorrero2011', 'Wikipedia (citing Davidson 2010): met 4 of 11 objectives; Blacka Table 4.1 surfing "Partially"; M&B p.4: designers say 7 of 9 criteria met',
        note='Quote: "The wave length is rather too intense and challenging [and it] is not quite as consistent as it should be" (Davidson 2010 via Wikipedia). Worked best near low tide, short steep sections, mostly bodyboarders. Reasons: built-vs-design differences, container failure from March 2011, closure 31 Mar 2011.')
    r.F('surfable_days_per_year', '77 (design baseline) -> 154 (design target)', 'days/yr', 'S', 'Breaker2018', 'card purpose field; target not an outcome', note='No measured after-construction number found.')
    r.F('durability', 'containers failed from March-April 2011 (offshore half of the axis at -0.8 to -2.8 m ACD; crest dip ~2 m); closed 31 Mar 2011; repairs aborted; ASR liquidated 2012; structure still present, shown on Garmin Navionics as a shoal with a 380-490 m2 drying patch', 'text', 'S', 'RendleDavidson2012', 'METHODS_3D s1, s3.10; Rendle & Davidson 2012')
    r.F('sediment_shoreline_outcome', 'within 6 months the beach in the lee and to the west accreted up to +60 m over >500 m (designers, M&B Fig 6); later monitoring (Rendle & Davidson 2012) found no noticeable long-term impact on the 0 m contour; accretion was predicted mainly around the -1 m contour; NSW review rates protection "Minor"', 'text', 'S', 'MeadBorrero2011+Blacka2013', 'M&B p.5; Blacka p.70, Table 4.1')
    r.F('cost_local', 3200000, 'GBP', 'S', 'Rendle2016', 'p.65-67: final about GBP 3.2 M for the reef (original GBP 600,000; ASR 2006 GBP 1.1 M); further GBP 700,000 repairs/marine park works (p.64)', price_year=2009, currency='GBP', note='Blacka Table 4.4: A$4.9 M in 2013 AUD, A$384/m3. Fixed-price contract (M&B p.4). Wider regeneration scheme about GBP 11 M.')
    r.F('shape_on_page', 'shown', 'category', 'S', None, '04_build/data/reefs.json footprint.display = True (read only)')
    r.F('model_3d', 'yes: as-built 2009 state (idealised loft on April 2011 survey seabed); confidence MEDIUM', 'text', 'S', None, SH + '3d/METHODS_3D.md s1, s6')
    r.F('depth_gap_m', round(T['gap'], 2), 'm', 'D', 'repo:' + SH + '3d/model.js; derive_boscombe.py', 'toe depth %.2f - crest depth %.2f on the crest transect; median over %d columns %.2f m (p10-p90 %.2f-%.2f)' % (T['toe_depth_msl'], T['crest_depth_msl'], PB['n_columns'], PB['medians']['gap'][0], PB['medians']['gap'][1], PB['medians']['gap'][2]))
    r.F('seaward_ramp_length_m', round(T['ramp'], 1), 'm', 'D', 'repo:' + SH + '3d/METHODS_3D.md E10 (flank 1:3, A7 +-30 %)', 'ramp of the idealised loft = 3 x (crest - bed) = %.1f m on the transect; median over columns %.1f m' % (T['ramp'], PB['medians']['ramp'][0]), note='Idealised loft (assumed 1:3 flanks); survey SW flank 1:3-1:4, NE flank 1:5-1:7, map median 1:5.8 (METHODS_3D KN "Side slopes").')
    r.F('mean_seaward_slope', round(T['gap'] / T['ramp'], 3), 'm/m', 'D', 'repo:' + SH + '3d/METHODS_3D.md E10', '= gap/ramp (1:%.1f); flank slope is an ASSUMPTION of the loft (1:3 +-30 %%)' % (T['ramp'] / T['gap']))
    return r
